INSERT INTO `instansi` VALUES (1,'STAN','Sekolah Tinggi Akuntansi Negara',65,80,156,301,'Dibawah naungan Kementerian Keuangan. Lulusan menjadi CPNS di DJP, DJPK, BPK, dll.',1,1,'2026-06-02 13:20:05'),(2,'STIS','Sekolah Tinggi Ilmu Statistik',65,80,156,301,'Dibawah naungan BPS. Fokus statistik, data science, dan big data.',1,2,'2026-06-02 13:20:05'),(3,'IPDN','Institut Pemerintahan Dalam Negeri',65,80,156,301,'Dibawah naungan Kemendagri. Menyediakan aparatur sipil negara daerah.',1,3,'2026-06-02 13:20:05'),(4,'STMKG','Sekolah Tinggi Meteorologi Klimatologi dan Geofisika',65,80,156,301,'Dibawah naungan BMKG. Fokus cuaca, iklim, dan mitigasi bencana.',1,4,'2026-06-02 13:20:05'),(5,'POLTEK_SSN','Politeknik Siber dan Sandi Negara',65,80,156,301,'Dibawah naungan BSSN. Fokus keamanan siber dan kriptografi.',1,5,'2026-06-02 13:20:05'),(6,'PTIK','Politeknik Ilmu Pemasyarakatan',65,80,156,301,'Dibawah naungan Kemenkumham. Fokus pemasyarakatan dan pengawasan.',1,6,'2026-06-02 13:20:05'),(7,'POLTEK_IMIGRASI','Politeknik Imigrasi',65,80,156,301,'Dibawah naungan Kemenkumham. Fokus keimigrasian dan pengawasan perbatasan.',1,7,'2026-06-02 13:20:05'),(8,'STIN','Sekolah Tinggi Intelijen Negara',65,80,156,301,'Dibawah naungan BIN. Fokus intelijen dan analisis ancaman.',1,8,'2026-06-02 13:20:05'),(9,'AKPOL','Akademi Kepolisian',65,80,156,301,'Dibawah naungan Polri. Fokus penegakan hukum dan keamanan.',1,9,'2026-06-02 13:20:05'),(10,'AKMIL','Akademi Militer',65,80,156,301,'Dibawah naungan TNI AD. Fokus pertahanan dan kepemimpinan militer.',1,10,'2026-06-02 13:20:05'),(11,'AAU','Akademi Angkatan Udara',65,80,156,301,'Dibawah naungan TNI AU. Fokus penerbangan dan pertahanan udara.',1,11,'2026-06-02 13:20:05'),(12,'AAL','Akademi Angkatan Laut',65,80,156,301,'Dibawah naungan TNI AL. Fokus kelautan dan pertahanan laut.',1,12,'2026-06-02 13:20:05');
