INSERT INTO `master_materi` VALUES (1,'TWK',NULL,'Nasionalisme','Menguji kesadaran berbangsa dan bernegara, semangat cinta tanah air, penggunaan produk dalam negeri, dukungan UMKM, penghormatan simbol negara, peristiwa bersejarah Indonesia (Sumpah Pemuda, Proklamasi, Pertempuran Surabaya), tokoh nasional.','sedang',1,'2026-06-02 11:21:38'),(2,'TWK',NULL,'Integritas','Menguji keselarasan pikiran-perkataan-perbuatan, jujur, disiplin, tanggung jawab, menolak suap/gratifikasi, lapor pelanggaran, pencegahan KKN (korupsi, kolusi, nepotisme), etika ASN ber-AKHLAK.','sedang',1,'2026-06-02 11:21:38'),(3,'TWK',NULL,'Bela Negara','Menguji kewajiban membela kedaulatan, keutuhan wilayah, keselamatan bangsa (UU No. 3/2002), komponen pertahanan (rakyat, wilayah, SDA), ancaman militer & non-militer, wawasan Nusantara, literasi digital & keamanan siber.','sedang',1,'2026-06-02 11:21:38'),(4,'TWK',NULL,'Pilar Negara','Menguji pemahaman Pancasila (5 silah), UUD 1945 (pembukaan, amandemen, lembaga negara), NKRI (kesatuan, Bhinneka Tunggal Ika), hak asasi manusia, demokrasi, rule of law.','sedang',1,'2026-06-02 11:21:38'),(5,'TWK',NULL,'Bahasa Indonesia','Menguji EYD (huruf kapital, tanda baca, penulisan kata), kalimat efektif (kesepadanan, keparalelan, kehematan, kelogisan), paragraf (deduktif, induktif, campuran), koherensi, peribahasa & ungkapan.','sedang',1,'2026-06-02 11:21:38'),(6,'TIU','verbal','Analogi','Menguji kemampuan menemukan hubungan logis antara dua pasang kata. Pola: sebab-akibat, fungsi, sinonim, antonim, bagian-keseluruhan, profesi-output, profesi-tempat, habitat, proses, bahan-produk.','sedang',1,'2026-06-02 11:21:38'),(7,'TIU','verbal','Silogisme','Menguji penarikan kesimpulan dari dua premis. Pola: universal affirmative (semua A adalah B), universal negative (tidak ada A yang B), particular affirmative (sebagian A adalah B). Hati-hati dengan \"sebagian\" dan \"tidak dapat disimpulkan\".','sulit',1,'2026-06-02 11:21:38'),(8,'TIU','verbal','Analitis','Menguji kemampuan menyimpulkan dari serangkaian pernyataan. Pola: urutan (lebih tinggi, lebih tua), penempatan posisi, jadwal logis. Gunakan diagram/garis untuk membantu.','sedang',1,'2026-06-02 11:21:38'),(9,'TIU','numerik','Berhitung','Operasi dasar cepat: perkalian 11, 25, 5; kuadrat berakhiran 5; persen, pecahan, proporsi; akar & pangkat. Latihan mental math.','mudah',1,'2026-06-02 11:21:38'),(10,'TIU','numerik','Deret Angka','Pola: aritmatika, geometri, kuadratik, pangkat 3, Fibonacci, selisih ganjil/genap, pola grup. Langkah: hitung selisih antar angka, cek apakah beda tetap/naik/teratur.','sedang',1,'2026-06-02 11:21:38'),(11,'TIU','numerik','Perbandingan','Perbandingan sebanding (a/b=c/d) dan berbalik nilai (a×b=c×d). Skala, pekerja-waktu, perbandingan kuantitatif.','sedang',1,'2026-06-02 11:21:38'),(12,'TIU','numerik','Soal Cerita','Jarak-waktu-kecepatan, diskon, untung-rugi, campuran, sistem persamaan linear. Langkah: identifikasi variabel, tulis rumus, substitusi, perhatikan satuan.','sedang',1,'2026-06-02 11:21:38'),(13,'TIU','figural','Analogi Figural','Transformasi gambar: ukuran, jumlah, rotasi, pencerminan, penambahan/pengurangan elemen, pengisian/warna, kombinasi.','sedang',1,'2026-06-02 11:21:38'),(14,'TIU','figural','Ketidaksamaan','Cari satu gambar yang berbeda. Pembeda: bentuk dasar, simetri, jumlah elemen, arah putaran, pengisian, posisi.','sedang',1,'2026-06-02 11:21:38'),(15,'TIU','figural','Serial Figural','Meneruskan pola gambar. Pola: ukuran naik/turun, jumlah elemen, rotasi bertahap, pengisian bertahap (kosong→setengah→penuh), penambahan garis.','sedang',1,'2026-06-02 11:21:38'),(16,'TKP',NULL,'Pelayanan Publik','Menguji sikap empati, responsif, ramah, tanggung jawab terhadap masyarakat. Prinsip SOLID (Speed, Ownership, Loyalty, Integrity, Discipline). Skor tertinggi: langsung membantu, minta maaf jika salah, solusi konkret.','sedang',1,'2026-06-02 11:21:38'),(17,'TKP',NULL,'Jejaring Kerja','Menguji kemampuan kerja sama tim, komunikasi terbuka, koordinasi, kolaborasi, resolusi konflik. Skor tertinggi: menghubungi anggota bermasalah, diskusi konstruktif, cari solusi win-win.','sedang',1,'2026-06-02 11:21:38'),(18,'TKP',NULL,'Sosial Budaya','Menguji toleransi, empati, inklusi, adaptasi terhadap keberagaman SARA. Skor tertinggi: menghormati adat, membela korban bullying, menerima kehidupan sederhana.','sedang',1,'2026-06-02 11:21:38'),(19,'TKP',NULL,'Teknologi Informasi','Menguji adaptabilitas teknologi baru, literasi digital (hoaks vs fakta), keamanan siber, etika medsos. Skor tertinggi: belajar aplikasi baru, klarifikasi hoaks, reset password prosedural.','sedang',1,'2026-06-02 11:21:38'),(20,'TKP',NULL,'Profesionalisme','Menguji integritas, disiplin, tanggung jawab, fleksibilitas, etika ASN ber-AKHLAK. Skor tertinggi: tolak suap tegas, terima kritik konstruktif, selesaikan tugas di luar job desk.','sedang',1,'2026-06-02 11:21:38'),(21,'TKP',NULL,'Kepribadian','Kepribadian dan karakteristik individu, sikap dalam menghadapi tantangan, kemampuan beradaptasi, ketahanan di bawah tekanan, empati, kejujuran, dan kerja sama dalam tim.','sedang',1,'2026-06-02 14:27:12'),(22,'TIU',NULL,'Logika Matematika','Penalaran logis dalam matematika, hubungan antar variabel, pola berpikir deduktif dan induktif, simbol matematika, dan pemecahan masalah non-rutin.','sedang',1,'2026-06-02 14:27:12'),(23,'TIU','figural','Analogi','Hubungan visual antar bentuk geometri: kesamaan, perbedaan, transformasi, dan korespondensi antar elemen gambar. Identifikasi pasangan bentuk yang memiliki pola relasi sama.','sedang',1,'2026-06-02 14:27:12'),(24,'TIU','figural','Serial','Pola urutan gambar: perubahan ukuran, rotasi, refleksi, penambahan/pengurangan elemen, dan transisi bentuk dalam deret visual.','sedang',1,'2026-06-02 14:27:12'),(25,'TWK',NULL,'Pancasila','Lima sila Pancasila, nilai-nilai luhur, makna filosofis dan praktis, implementasi dalam kehidupan berbangsa dan bernegara, serta peran Pancasila sebagai dasar negara.','sedang',1,'2026-06-02 14:27:12'),(26,'TWK',NULL,'Sejarah','Peristiwa penting perjuangan bangsa Indonesia, tokoh nasional, proklamasi kemerdekaan, pergerakan nasional, dan warisan sejarah dalam pembentukan identitas bangsa.','sedang',1,'2026-06-02 14:27:12'),(27,'TWK',NULL,'UUD 1945','Struktur dan isi UUD 1945, fungsi lembaga negara (DPR, DPD, MPR, BPK, MK), hak dan kewajiban warga negara, serta perubahan UUD 1945.','sedang',1,'2026-06-02 14:27:12');
/*!40000 ALTER TABLE `master_materi` ENABLE KEYS */;
UNLOCK TABLES;

