LOCK TABLES `materi` WRITE;
/*!40000 ALTER TABLE `materi` DISABLE KEYS */;
INSERT INTO `materi` VALUES (1,'TIU',NULL,'Deret Angka: Aritmatika & Geometri','<h3>Pola Deret Angka</h3><p><b>Aritmatika:</b> beda tetap (contoh: 2,5,8,11 beda +3).<br><b>Geometri:</b> rasio tetap (contoh: 3,6,12,24 x2).<br><b>Fibonacci:</b> jumlah 2 angka sebelumnya.<br><b>Kuadrat:</b> 1,4,9,16,25.<br><b>Kubik:</b> 1,8,27,64.</p><p><b>Tips:</b> Selisihkan antar angka terlebih dahulu untuk menemukan pola.</p>','https://id.wikipedia.org/wiki/Deret_aritmatika',1,'2026-06-02 16:48:23'),(2,'TIU',NULL,'Deret Angka: Prima & Pangkat','<h3>Deret Khusus</h3><p><b>Bilangan Prima:</b> 2,3,5,7,11,13,17,19... hanya habis dibagi 1 dan dirinya.<br><b>Pangkat:</b> 2,4,8,16,32 (2^n).<br><b>Segitiga:</b> 1,3,6,10,15 (n(n+1)/2).</p>','https://id.wikipedia.org/wiki/Bilangan_prima',2,'2026-06-02 16:48:23'),(3,'TIU',NULL,'Berhitung Cepat','<h3>Teknik Berhitung</h3><p><b>Perkalian:</b> 25x4=100, 125x8=1000.<br><b>Persen:</b> 10% = bagi 10, 25% = bagi 4.<br><b>Pembulatan:</b> 198x5 = (200x5)-10 = 990.</p><p><b>Tips:</b> Pecah angka besar jadi kelipatan 10 atau 100.</p>','https://www.zenius.net/cpns/tiu-berhitung',3,'2026-06-02 16:48:23'),(4,'TIU',NULL,'Perbandingan & Proporsi','<h3>Rumus Perbandingan</h3><p><b>Harga:</b> a/b = c/d → d = (b x c)/a.<br><b>Pekerja:</b> P1 x H1 = P2 x H2.<br><b>Kecepatan:</b> v = s/t, t = s/v, s = v x t.</p><p><b>Tips:</b> Samakan satuan sebelum menghitung.</p>','https://id.wikipedia.org/wiki/Perbandingan',4,'2026-06-02 16:48:23'),(5,'TIU',NULL,'Logika Matematika','<h3>Logika</h3><p><b>Konjungsi (AND):</b> benar jika keduanya benar.<br><b>Disjungsi (OR):</b> salah jika keduanya salah.<br><b>Implikasi:</b> P→Q, salah hanya jika P benar Q salah.<br><b>Bikonjungsi:</b> P↔Q, benar jika sama.</p>','https://id.wikipedia.org/wiki/Logika_matematika',5,'2026-06-02 16:48:23'),(6,'TIU',NULL,'Analitis & Penalaran','<h3>Teknik Analitis</h3><p>Gunakan diagram/skema untuk menyusun urutan.<br>Contoh: A>B>C → A paling besar.<br>Susun informasi sesuai posisi (utara-selatan, besar-kecil).</p><p><b>Tips:</b> Tulis ulang informasi dalam bentuk garis bilangan.</p>','https://www.zenius.net/cpns/tiu-penalaran',6,'2026-06-02 16:48:23'),(7,'TIU',NULL,'Analogi Verbal','<h3>Hubungan Kata</h3><p><b>Sinonim:</b> makna sama.<br><b>Antonim:</b> makna berlawanan.<br><b>Sebab-akibat:</b> api → panas.<br><b>Fungsi:</b> pena → menulis.</p><p><b>Tips:</b> Identifikasi hubungan pasangan pertama lalu cari pasangan kedua dengan hubungan identik.</p>','https://id.wikipedia.org/wiki/Analogi',7,'2026-06-02 16:48:23'),(8,'TIU',NULL,'Silogisme','<h3>Silogisme Kategoris</h3><p><b>Modus Barbara:</b> Semua A adalah B, Semua B adalah C → Semua A adalah C.<br><b>Modus Celarent:</b> Tidak ada A adalah B, Semua C adalah B → Tidak ada C adalah A.<br><b>Modus Darii:</b> Semua A adalah B, Beberapa C adalah A → Beberapa C adalah B.</p><p><b>Tips:</b> Gambar lingkaran (diagram Venn) untuk memudahkan.</p>','https://id.wikipedia.org/wiki/Silogisme',8,'2026-06-02 16:48:23'),(9,'TIU',NULL,'Figural: Serial & Ketidaksamaan','<h3>Pola Figural</h3><p><b>Serial:</b> ukuran, jumlah, posisi, rotasi.<br><b>Ketidaksamaan:</b> bentuk berbeda dari kelompok.<br>Perhatikan arah, warna, jumlah elemen.</p>','https://www.zenius.net/cpns/tiu-figural',9,'2026-06-02 16:48:23'),(10,'TIU',NULL,'Soal Cerita Matematika','<h3>Strategi</h3><p>1. Identifikasi variabel yang diketahui.<br>2. Tentukan rumus yang sesuai.<br>3. Hitung step-by-step.<br>4. Periksa satuan.</p><p><b>Tips:</b> Buat sketsa/gambar untuk soal geometri.</p>','https://id.wikipedia.org/wiki/Pemecahan_masalah_matematika',10,'2026-06-02 16:48:23'),(11,'TWK',NULL,'Sejarah Kemerdekaan Indonesia','<h3>Peristiwa Penting</h3><p><b>1908:</b> Kebangkitan Nasional (Budi Utomo).<br><b>1928:</b> Sumpah Pemuda.<br><b>1945:</b> Proklamasi 17 Agustus.<br><b>1955:</b> Konferensi Asia-Afrika.<br><b>1965:</b> G30S/PKI.<br><b>1998:</b> Reformasi.</p>','https://id.wikipedia.org/wiki/Sejarah_Indonesia',1,'2026-06-02 16:48:23'),(12,'TWK',NULL,'UUD 1945 & Amandemen','<h3>Struktur UUD 1945</h3><p><b>Pembukaan:</b> 4 alinea.<br><b>Bab:</b> 16 bab.<br><b>Amandemen:</b> 4 kali (1999-2002).<br><b>Mahkamah Konstitusi:</b> hasil amandemen ke-3.<br><b>Komisi Yudisial:</b> hasil amandemen ke-3.</p>','https://id.wikipedia.org/wiki/UUD_1945',2,'2026-06-02 16:48:23'),(13,'TWK',NULL,'Pancasila: Sila & Lambang','<h3>5 Sila & Lambang</h3><p>1. Ketuhanan → Bintang<br>2. Kemanusiaan → Rantai<br>3. Persatuan → Pohon Beringin<br>4. Kerakyatan → Kepala Banteng<br>5. Keadilan → Padi & Kapas</p><p>Rumus final oleh Soekarno, disahkan PPKI 18 Agustus 1945.</p>','https://id.wikipedia.org/wiki/Pancasila',3,'2026-06-02 16:48:23'),(14,'TWK',NULL,'Nasionalisme & Pahlawan','<h3>Pahlawan Nasional</h3><p><b>Aceh:</b> Cut Nyak Dien, Teuku Umar.<br><b>Jawa:</b> Jenderal Soedirman.<br><b>Kalimantan:</b> Pangeran Antasari.<br><b>Sulawesi:</b> Sultan Hasanuddin.<br><b>Sumatera:</b> Pattimura.</p><p>Hari Pahlawan: 10 November.</p>','https://id.wikipedia.org/wiki/Pahlawan_nasional_Indonesia',4,'2026-06-02 16:48:23'),(15,'TWK',NULL,'Bahasa Indonesia Baku','<h3>EYD & Kata Baku</h3><p><b>Kata baku:</b> sebentar→sesaat, sekalian→segala, mempunyai→memiliki, sekedar→sekadar, terlanjur→telanjur, sebetulnya→sebenarnya.</p><p>Gunakan KBBI (kbbi.kemdikbud.go.id) sebagai acuan.</p>','https://kbbi.kemdikbud.go.id/',5,'2026-06-02 16:48:23'),(16,'TWK',NULL,'Pilar Negara & Bhinneka Tunggal Ika','<h3>4 Pilar</h3><p>1. Pancasila (ideologi)<br>2. UUD 1945 (dasar hukum)<br>3. NKRI (bentuk negara)<br>4. Bhinneka Tunggal Ika (semboyan)</p><p>Arti Bhinneka Tunggal Ika: Berbeda-beda tetap satu.</p>','https://id.wikipedia.org/wiki/Pilar_Negara',6,'2026-06-02 16:48:23'),(17,'TWK',NULL,'Integritas & Anti Korupsi','<h3>Anti Korupsi</h3><p><b>KPK:</b> Komisi Pemberantasan Korupsi.<br><b>UU Tipikor:</b> Tindak Pidana Korupsi.<br><b>Gratifikasi:</b> pemberian yang berpengaruh pada keputusan.<br><b>Saksi:</b> perlindungan bagi pelapor korupsi.</p>','https://www.kpk.go.id/',7,'2026-06-02 16:48:23'),(18,'TWK',NULL,'Bela Negara','<h3>Sistem Pertahanan</h3><p><b>SISHANKAMRATA:</b> Sistem Pertahanan dan Keamanan Rakyat Semesta.<br><b>TNI:</b> komponen utama pertahanan.<br><b>Kewajiban:</b> wajib militer/sipil.<br><b>Alutsista:</b> peralatan tempur.</p>','https://id.wikipedia.org/wiki/Bela_negara',8,'2026-06-02 16:48:23'),(19,'TKP',NULL,'Pelayanan Publik Prima','<h3>Standar Pelayanan</h3><p><b>5 Pelayanan Prima:</b> Produk, Proses, Pelayanan fisik, Penanganan keluhan, Citra.<br><b>Maklumat:</b> janji keterbukaan standar pelayanan.<br><b>Sistem antre:</b> efisiensi dan keadilan.</p><p><b>Tips:</b> Selalu prioritaskan kepentingan masyarakat.</p>','https://www.menpan.go.id/',1,'2026-06-02 16:48:23'),(20,'TKP',NULL,'Jejaring Kerja & Kerja Sama','<h3>Tim Kerja</h3><p><b>Komunikasi:</b> aktif, jujur, konstruktif.<br><b>Konflik:</b> cari solusi win-win.<br><b>Delegasi:</b> sesuai kompetensi.<br><b>Evaluasi:</b> rutin dan objektif.</p>','https://www.zenius.net/cpns/tkp-kerjasama',2,'2026-06-02 16:48:23'),(21,'TKP',NULL,'Sosial Budaya & Keberagaman','<h3>Kesadaran Sosial Budaya</h3><p>Hormati adat istiadat daerah.<br>Pahami nilai-nilai lokal.<br>Toleransi antar umat beragama.<br>Kemampuan beradaptasi di lingkungan baru.</p>','https://id.wikipedia.org/wiki/Keberagaman_di_Indonesia',3,'2026-06-02 16:48:23'),(22,'TKP',NULL,'Profesionalisme & Integritas','<h3>Profesionalisme ASN</h3><p><b>Netral:</b> tidak memihak.<br><b>Jujur:</b> laporkan kesalahan.<br><b>Tanggung jawab:</b> akui dan perbaiki.<br><b>Etos kerja:</b> disiplin, tepat waktu, berkualitas.</p>','https://id.wikipedia.org/wiki/Profesionalisme',4,'2026-06-02 16:48:23'),(23,'TKP',NULL,'Teknologi Informasi & Adaptasi','<h3>Adaptasi Teknologi</h3><p>Mau belajar aplikasi baru.<br>Manfaatkan digitalisasi layanan.<br>Jaga keamanan data dan privasi.<br>Tanggap isu hoaks/misinformasi.</p>','https://www.kominfo.go.id/',5,'2026-06-02 16:48:23'),(24,'TKP',NULL,'Kepribadian & Kecerdasan Emosional','<h3>Kecerdasan Emosional</h3><p><b>Kesadaran diri:</b> kenali emosi sendiri.<br><b>Pengendalian:</b> jangan reaktif.<br><b>Motivasi:</b> tetap optimis.<br><b>Empati:</b> pahami perasaan orang lain.<br><b>Kemampuan sosial:</b> bangun relasi positif.</p>','https://id.wikipedia.org/wiki/Kecerdasan_emosional',6,'2026-06-02 16:48:23');
/*!40000 ALTER TABLE `materi` ENABLE KEYS */;
UNLOCK TABLES;

