INSERT INTO `passages` VALUES (1,'TIU','verbal','Analitis','Jadwal Rapat','Ada lima orang yang akan mengadakan rapat: Andi, Budi, Cici, Dedi, dan Evi. Rapat akan diadakan dari hari Senin sampai Jumat, satu orang per hari. Andi tidak bisa hari Senin. Budi hanya bisa hari Rabu atau Jumat. Cici harus sebelum Dedi. Dedi tidak bisa hari Jumat. Evi harus di hari Selasa atau Kamis.',1,'2026-06-02 15:18:25');
