--
-- Table structure for table `questions`
--

DROP TABLE IF EXISTS `questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `questions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `subtes` enum('TKP','TIU','TWK') NOT NULL,
  `tipe` varchar(20) DEFAULT NULL COMMENT 'verbal|numerik|figural untuk TIU',
  `topik` varchar(100) NOT NULL,
  `pertanyaan` text NOT NULL,
  `pilihan_a` text NOT NULL,
  `pilihan_b` text NOT NULL,
  `pilihan_c` text NOT NULL,
  `pilihan_d` text NOT NULL,
  `pilihan_e` text NOT NULL,
  `jawaban_benar` char(1) NOT NULL,
  `bobot_tkp` int(11) DEFAULT NULL COMMENT '1-5 untuk TKP; NULL untuk TIU/TWK',
  `bobot_a` int(11) DEFAULT NULL,
  `bobot_b` int(11) DEFAULT NULL,
  `bobot_c` int(11) DEFAULT NULL,
  `bobot_d` int(11) DEFAULT NULL,
  `bobot_e` int(11) DEFAULT NULL,
  `pembahasan` text NOT NULL,
  `tips_trick` text DEFAULT NULL,
  `related_links` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`related_links`)),
  `materi_id` int(11) DEFAULT NULL,
  `image_url` varchar(255) DEFAULT NULL,
  `passage_id` int(11) DEFAULT NULL,
  `passage_order` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `needs_revision` tinyint(1) NOT NULL DEFAULT 0,
  `revision_status` varchar(20) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pertanyaan` (`pertanyaan`) USING HASH,
  KEY `passage_id` (`passage_id`),
  CONSTRAINT `questions_ibfk_1` FOREIGN KEY (`passage_id`) REFERENCES `passages` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3652 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `questions`
