--
-- Table structure for table `session_subtes`
--

DROP TABLE IF EXISTS `session_subtes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `session_subtes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `session_id` int(11) NOT NULL,
  `subtes` enum('TKP','TIU','TWK') NOT NULL,
  `durasi_menit` int(11) NOT NULL DEFAULT 30,
  `jumlah_soal` int(11) NOT NULL DEFAULT 30,
  `passing_grade` int(11) NOT NULL DEFAULT 0,
  `nilai` int(11) NOT NULL DEFAULT 0 COMMENT 'Nilai akhir subtes setelah finish',
  `waktu_mulai_subtes` timestamp NULL DEFAULT NULL,
  `urutan` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_session_subtes` (`session_id`,`subtes`),
  KEY `idx_session_subtes_session` (`session_id`),
  CONSTRAINT `session_subtes_ibfk_1` FOREIGN KEY (`session_id`) REFERENCES `tryout_sessions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=616 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

