DROP TABLE IF EXISTS `soal_ai_cache`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `soal_ai_cache` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `master_materi_id` int(11) NOT NULL,
  `pertanyaan` text NOT NULL,
  `pilihan_a` text NOT NULL,
  `pilihan_b` text NOT NULL,
  `pilihan_c` text NOT NULL,
  `pilihan_d` text NOT NULL,
  `pilihan_e` text NOT NULL,
  `jawaban_benar` char(1) NOT NULL,
  `bobot_tkp` int(11) DEFAULT NULL,
  `bobot_a` int(11) DEFAULT NULL,
  `bobot_b` int(11) DEFAULT NULL,
  `bobot_c` int(11) DEFAULT NULL,
  `bobot_d` int(11) DEFAULT NULL,
  `bobot_e` int(11) DEFAULT NULL,
  `pembahasan` text NOT NULL,
  `image_url` varchar(255) DEFAULT NULL,
  `passage_id` int(11) DEFAULT NULL,
  `tingkat_kesulitan` enum('mudah','sedang','sulit') DEFAULT 'sedang',
  `digenerate_pada` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `master_materi_id` (`master_materi_id`),
  KEY `passage_id` (`passage_id`),
  CONSTRAINT `soal_ai_cache_ibfk_1` FOREIGN KEY (`master_materi_id`) REFERENCES `master_materi` (`id`) ON DELETE CASCADE,
  CONSTRAINT `soal_ai_cache_ibfk_2` FOREIGN KEY (`passage_id`) REFERENCES `passages` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=229 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
