--
-- Table structure for table `tryout_sessions`
--

DROP TABLE IF EXISTS `tryout_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tryout_sessions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `nama` varchar(100) NOT NULL,
  `durasi_tkp` int(11) DEFAULT 45,
  `durasi_tiu` int(11) DEFAULT 35,
  `durasi_twk` int(11) DEFAULT 30,
  `jumlah_tkp` int(11) DEFAULT 45,
  `jumlah_tiu` int(11) DEFAULT 35,
  `jumlah_twk` int(11) DEFAULT 30,
  `passing_tkp` int(11) DEFAULT 126,
  `passing_tiu` int(11) DEFAULT 80,
  `passing_twk` int(11) DEFAULT 65,
  `passing_total` int(11) DEFAULT 271,
  `waktu_mulai` datetime DEFAULT NULL,
  `waktu_selesai` datetime DEFAULT NULL,
  `nilai_tkp` int(11) DEFAULT 0,
  `nilai_tiu` int(11) DEFAULT 0,
  `nilai_twk` int(11) DEFAULT 0,
  `total_nilai` int(11) DEFAULT 0,
  `status` enum('berjalan','selesai','gagal') DEFAULT 'berjalan',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `tryout_sessions_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=150 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

